const steps=[
 {section:'Upper body and glass',title:'Windscreen',image:'assets/windscreen.jpg',copy:'Photograph the windscreen from outside, straight on, with the full glass from edge to edge in the frame.'},
 {section:'Upper body and glass',title:'Hood',image:'assets/hood.jpg',copy:'Stand at the front and capture the entire hood in one photo, from the windscreen to the grille.'},
 {section:'Upper body and glass',title:'Roof',image:'assets/roof.jpg',copy:'Capture the whole roof, including any roof rails. If you cannot see it from the ground, hold your phone up above the car.'},
 {section:'Upper body and glass',title:'Lights',image:'assets/lights.jpg',copy:'Photograph all the lights: both headlights, both rear lights, and the indicators.'},
 {section:'Upper body and glass',title:'Windows',image:'assets/windows.jpg',copy:'Photograph every window — both side windows, the rear window, and any sunroof.'},
 {section:'Upper body and glass',title:'Side mirrors',image:'assets/mirrors.jpg',copy:'Photograph both mirrors, one at a time. Include the housing and the mirror glass.'},
 {section:'Lower body and wheels',title:'Left side',image:'assets/bumpers.jpg',copy:'Step back and capture the full left side of the car from bumper to bumper.'},
 {section:'Lower body and wheels',title:'Right side',image:'assets/bumpers.jpg',copy:'Step back and capture the full right side of the car from bumper to bumper.'},
 {section:'Lower body and wheels',title:'Wheels',image:'assets/bumpers.jpg',copy:'Photograph all four wheels individually, keeping each tire and rim fully visible.'},
 {section:'Lower body and wheels',title:'Front and rear bumpers',image:'assets/bumpers.jpg',copy:'Take one straight-on photo of the front bumper and one of the rear bumper.'},
 {section:'Inside the car',title:'Glovebox',image:'assets/windows.jpg',copy:'Open the glovebox and photograph the full compartment in clear light.'},
 {section:'Inside the car',title:'Trunk',image:'assets/roof.jpg',copy:'Open the trunk and capture the entire cargo area, including the floor and side panels.'}
];
let current=0;const completed=new Set(JSON.parse(localStorage.getItem('inspection-completed')||'[]'));const capturedPhotos=new Map();
const $=id=>document.getElementById(id);const overview=$('overview'),guide=$('guide');
function renderOverview(){const groups=[...new Set(steps.map(s=>s.section))];$('sectionList').innerHTML=groups.map((group,i)=>`<section><div class="section-heading"><small>${i===0?'Start here':i===groups.length-1?'And finally':'Next'}</small><h3>${group}</h3></div><div class="card-grid">${steps.map((s,n)=>s.section===group?`<button class="photo-card ${completed.has(n)?'done':''}" data-step="${n}"><img src="${s.image}" alt="${s.title}"><span>${s.title}</span></button>`:'').join('')}</div></section>`).join('');document.querySelectorAll('.photo-card').forEach(b=>b.addEventListener('click',()=>openStep(+b.dataset.step)));updateProgress()}
function openStep(index){current=Math.max(0,Math.min(index,steps.length-1));const s=steps[current],photo=capturedPhotos.get(current);overview.classList.add('hidden');guide.classList.remove('hidden');$('guideImage').src=photo?.url||s.image;$('guideImage').alt=photo?`Captured photo: ${s.title}`:`Example photo: ${s.title}`;$('sectionBadge').textContent=s.section;$('stepCount').textContent=`Photo ${current+1} of ${steps.length}`;$('guideTitle').textContent=s.title;$('guideCopy').textContent=s.copy;$('cameraLabel').textContent=photo?'Retake photo':'Take photo';$('cameraBtn').classList.toggle('captured',!!photo);$('savePhotoBtn').classList.toggle('hidden',!photo);$('captureStatus').textContent=photo?'Tap Save to iPhone Photos, then choose Save Image.':'Opens the rear camera on your phone.';$('prevBtn').disabled=current===0;$('nextBtn').innerHTML=current===steps.length-1?'Finish <span>✓</span>':'Next photo <span>→</span>';$('dots').innerHTML=steps.map((_,i)=>`<span class="dot ${i===current?'active':''}"></span>`).join('');window.scrollTo(0,0)}
function closeGuide(){guide.classList.add('hidden');overview.classList.remove('hidden');renderOverview();window.scrollTo(0,0)}
function updateProgress(){const pct=Math.round(completed.size/steps.length*100);$('progressText').textContent=`${pct}%`;$('progressRing').style.background=`conic-gradient(var(--blue) ${pct*3.6}deg,#e9edf3 0deg)`}
$('cameraBtn').addEventListener('click',()=>{$('cameraInput').value='';$('cameraInput').click()});$('cameraInput').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;const old=capturedPhotos.get(current);if(old)URL.revokeObjectURL(old.url);capturedPhotos.set(current,{url:URL.createObjectURL(file),name:file.name,file});completed.add(current);localStorage.setItem('inspection-completed',JSON.stringify([...completed]));updateProgress();openStep(current)});$('savePhotoBtn').addEventListener('click',async()=>{const photo=capturedPhotos.get(current);if(!photo)return;try{if(navigator.canShare?.({files:[photo.file]})){await navigator.share({files:[photo.file],title:`Car inspection - ${steps[current].title}`});$('captureStatus').textContent='Photo saved or shared successfully.'}else{const link=document.createElement('a');link.href=photo.url;link.download=`car-inspection-${steps[current].title.toLowerCase().replaceAll(' ','-')}.jpg`;link.click();$('captureStatus').textContent='Photo downloaded. Open it and choose Save Image.'}}catch(error){if(error.name!=='AbortError')$('captureStatus').textContent='Could not open sharing. Please try again.'}});$('prevBtn').addEventListener('click',()=>openStep(current-1));$('nextBtn').addEventListener('click',()=>current===steps.length-1?closeGuide():openStep(current+1));$('backBtn').addEventListener('click',()=>guide.classList.contains('hidden')?history.back():closeGuide());document.addEventListener('keydown',e=>{if(guide.classList.contains('hidden'))return;if(e.key==='ArrowRight')$('nextBtn').click();if(e.key==='ArrowLeft'&&current>0)$('prevBtn').click();if(e.key==='Escape')closeGuide()});renderOverview();
